/usr/bin/python3 - "$1" <<'PYEOF'
import json, os, re, sys, urllib.request

query = (sys.argv[1] if len(sys.argv) > 1 else "").strip()
api_key = os.environ.get("LINEAR_API_KEY", "").strip()

def out(items):
    print(json.dumps({"items": items}))
    sys.exit(0)

if not api_key:
    out([{
        "title": "Linear API key not set",
        "subtitle": "Open workflow Configuration in Alfred and paste a personal API key (linear.app/settings/account/security)",
        "valid": False,
    }])

if len(query) < 2:
    out([{
        "title": "Open a Linear issue",
        "subtitle": "Type an issue ID (e.g. ENG-123) or search terms",
        "valid": False,
    }])

def gql(q, variables):
    req = urllib.request.Request(
        "https://api.linear.app/graphql",
        data=json.dumps({"query": q, "variables": variables}).encode(),
        headers={"Content-Type": "application/json", "Authorization": api_key},
    )
    with urllib.request.urlopen(req, timeout=10) as r:
        return json.loads(r.read())

FIELDS = "identifier title url state { name } assignee { displayName } priorityLabel project { name }"

issues = []
try:
    # Fast path: exact issue identifier
    if re.fullmatch(r"[A-Za-z0-9]+-\d+", query):
        try:
            data = gql("query($id: String!) { issue(id: $id) { %s } }" % FIELDS,
                       {"id": query.upper()})
            issue = (data.get("data") or {}).get("issue")
            if issue:
                issues = [issue]
        except Exception:
            pass
    if not issues:
        data = gql("query($q: String!) { searchIssues(term: $q, first: 8) { nodes { %s } } }" % FIELDS,
                   {"q": query})
        issues = ((data.get("data") or {}).get("searchIssues") or {}).get("nodes") or []
except Exception as e:
    out([{"title": "Linear request failed", "subtitle": str(e), "valid": False}])

items = []
for i in issues:
    state = (i.get("state") or {}).get("name") or ""
    assignee = (i.get("assignee") or {}).get("displayName") or "Unassigned"
    prio = i.get("priorityLabel") or ""
    project = (i.get("project") or {}).get("name") or ""
    subtitle = " · ".join(x for x in [state, assignee, prio, project] if x)
    url = i["url"]
    items.append({
        "uid": i["identifier"],
        "title": "%s  %s" % (i["identifier"], i["title"]),
        "subtitle": subtitle,
        "arg": url,
        "autocomplete": i["identifier"],
        "quicklookurl": url,
        "text": {"copy": url, "largetype": "%s\n%s\n%s" % (i["identifier"], i["title"], subtitle)},
        "mods": {
            "cmd": {
                "arg": url.replace("https://linear.app/", "linear://"),
                "subtitle": "Open in Linear.app",
            }
        },
    })

if not items:
    items = [{"title": "No issues matching '%s'" % query, "valid": False}]
out(items)
PYEOF
